package profile

import (
	"fmt"
	"strconv"
	"strings"
)

// QUIC is how a browser speaks QUIC version 1 (RFC 9000) for HTTP/3:
// Initial packets, connection IDs, transport parameters, acknowledgements,
// loss recovery, credit, Version Negotiation, resumption, stream limits and
// close.
// Generated by internal/harness/cmd/h3gen from the h3 captures; not
// hand-edited.
type QUIC struct {
	// Version is the QUIC version of every packet: 1.
	Version uint32 `json:"version"`
	// DatagramSize is the length Initial-carrying datagrams are padded to,
	// and the longest datagram the browser sends.
	DatagramSize int `json:"datagramSize"`
	// Padding is where a datagram carrying an Initial packet is padded:
	// PaddingScattered, PaddingTrailing or PaddingEnd.
	Padding string `json:"padding"`
	// Crypto is how the ClientHello is cut into CRYPTO frames and Initial
	// packets.
	Crypto QUICCrypto `json:"crypto"`
	// PacketNumbers is how packet numbers are assigned:
	// PacketNumbersShared, PacketNumbersRandomInitial or
	// PacketNumbersPerSpace.
	PacketNumbers string `json:"packetNumbers"`
	// DCIDLength is the length of the first Initial's random Destination
	// Connection ID; with DCIDLengthBiased, the shortest length it picks.
	DCIDLength int `json:"dcidLength"`
	// DCIDLengthRule is how DCIDLength is picked per connection: empty is
	// always DCIDLength; DCIDLengthBiased.
	DCIDLengthRule string `json:"dcidLengthRule,omitempty"`
	// SCIDLength is the length of the client's own connection IDs. Zero
	// means it issues none.
	SCIDLength int `json:"scidLength"`
	// NewConnectionIDs is how many connection IDs the client issues with
	// NEW_CONNECTION_ID to a server whose active_connection_id_limit is 4.
	// Zero with SCIDLength 0.
	NewConnectionIDs int `json:"newConnectionIds,omitempty"`
	// TransportParameters are the ClientHello's quic_transport_parameters
	// (RFC 9000, section 18) in one observed order, permuted as
	// TransportParameterOrder says.
	TransportParameters []TransportParameter `json:"transportParameters"`
	// TransportParameterOrder is TransportParameterOrderFixed,
	// TransportParameterOrderShuffled or TransportParameterOrderRotated.
	TransportParameterOrder string `json:"transportParameterOrder"`
	// AckInitial acknowledges the server's Initial packets. Otherwise the
	// Initial keys are dropped at the first Handshake packet.
	AckInitial bool `json:"ackInitial,omitempty"`
	// AckBeforeFinished acknowledges the server's first flight in
	// datagrams before the one carrying the Finished; otherwise the
	// Handshake ACK goes with the Finished.
	AckBeforeFinished bool `json:"ackBeforeFinished,omitempty"`
	// Coalesce puts packets of different spaces that are ready together in
	// one datagram (RFC 9000, section 12.2); otherwise one per datagram.
	Coalesce bool `json:"coalesce,omitempty"`
	// AckDelay is what an ACK frame's ACK Delay says: AckDelayActual or
	// AckDelayConstant.
	AckDelay string `json:"ackDelay"`
	// AckDelayConstant is the range a connection's constant ACK Delay is
	// drawn from, as sent (before ack_delay_exponent).
	AckDelayConstant *Range `json:"ackDelayConstant,omitempty"`
	// AckOnlyLimit: after this many consecutive ACK-only 1-RTT packets,
	// the next carries AckOnlyFrame to make it ack-eliciting. Zero: never.
	AckOnlyLimit int    `json:"ackOnlyLimit,omitempty"`
	AckOnlyFrame string `json:"ackOnlyFrame,omitempty"`
	// SpinBit is how the latency spin bit of 1-RTT packets is set:
	// SpinBitZero, SpinBitRandom or SpinBitSpin.
	SpinBit string `json:"spinBit"`
	// Tokens sends the server's last NEW_TOKEN token on a new connection.
	Tokens bool `json:"tokens,omitempty"`
	// ZeroRTT resumes QUIC connections with a ticket an earlier QUIC
	// connection to the origin received, and sends a resumed connection's
	// first requests in 0-RTT (HTTP3.EarlyData). False: every QUIC
	// connection is a full handshake (resuming without 0-RTT was never
	// captured). Independent of TLS.Resumption, which is TCP's: Safari
	// resumes over QUIC only.
	ZeroRTT bool `json:"zeroRtt,omitempty"`
	// CloseReply answers the server's CONNECTION_CLOSE with a NO_ERROR
	// CONNECTION_CLOSE (frame type 0x1d) plus ACK; otherwise silence.
	// Unused connections end by max_idle_timeout.
	CloseReply bool `json:"closeReply,omitempty"`
	// Loss is handshake probing, give-up, and path degrading.
	Loss QUICLoss `json:"loss"`
	// KeepAlive is the PING sent while a request waits on a quiet
	// connection.
	KeepAlive QUICKeepAlive `json:"keepAlive"`
	// Ack is how often the client acknowledges a bulk receive.
	Ack QUICAck `json:"ack"`
	// Credit is how the client returns flow-control credit.
	Credit QUICCredit `json:"credit"`
	// KeyUpdate is how the client takes part in 1-RTT key updates (RFC
	// 9001, section 6).
	KeyUpdate QUICKeyUpdate `json:"keyUpdate"`
	// VersionNegotiation is what a Version Negotiation packet makes the
	// client do.
	VersionNegotiation QUICVersionNegotiation `json:"versionNegotiation"`
	// StreamsBlocked is the STREAMS_BLOCKED the client sends while its
	// requests wait for the server's limit on bidirectional streams. Nil:
	// not measured; the client sends none.
	StreamsBlocked *QUICStreamsBlocked `json:"streamsBlocked,omitempty"`
}

// QUICStreamsBlocked is when a client sends STREAMS_BLOCKED (RFC 9000,
// section 19.14). A request made when the streams the server allows are
// all taken waits on its connection, in the order made, until MAX_STREAMS
// raises the limit. Every frame is for bidirectional streams (type 0x16)
// and carries the limit the client has at the time.
type QUICStreamsBlocked struct {
	// AtRequest is what a request made at the limit sends, each frame in a
	// packet of its own: StreamsBlockedEveryRequest or
	// StreamsBlockedFirstRequest.
	AtRequest string `json:"atRequest"`
	// AfterRaise is what a waiting request sends when, the limit raised,
	// it opens its stream and takes the last one the limit allows:
	// StreamsBlockedRaiseAlways, StreamsBlockedRaiseWaiting, or empty for
	// nothing.
	AfterRaise string `json:"afterRaise,omitempty"`
}

// Values of QUICStreamsBlocked.AtRequest.
const (
	// StreamsBlockedEveryRequest sends one for every request made at the
	// limit, the same limit again for each (Chrome).
	StreamsBlockedEveryRequest = "every_request"
	// StreamsBlockedFirstRequest sends one for the first request made at
	// a limit only; a limit once sent is never sent again (Firefox,
	// Safari).
	StreamsBlockedFirstRequest = "first_request"
)

// Values of QUICStreamsBlocked.AfterRaise.
const (
	// StreamsBlockedRaiseAlways sends one with the new limit right after
	// that stream's STREAM frame, whether or not another request still
	// waits (Chrome). Where a raise in two MAX_STREAMS frames lets two
	// waiting requests open, the first sends one too, with the first
	// frame's limit, if it opens its stream before the second frame is
	// read: Chrome sent one after each stream in 9 of 12 such raises, one
	// after the second only in 3.
	StreamsBlockedRaiseAlways = "always"
	// StreamsBlockedRaiseWaiting sends one with the new limit right
	// before that stream's STREAM frame, only while another request still
	// waits, and not for a limit already sent (Firefox).
	StreamsBlockedRaiseWaiting = "waiting"
)

// QUICLoss is how a client recovers from loss where it differs from RFC
// 9002. Probe timeouts double after each unanswered probe.
type QUICLoss struct {
	// InitialPTOMillis is the first probe timeout with no RTT sample.
	// Zero: not measured.
	InitialPTOMillis int `json:"initialPtoMs,omitempty"`
	// CachedRTT starts a resumed connection from the RTT of the connection
	// whose ticket it resumes (RFC 9002, section 6.2.2).
	CachedRTT bool `json:"cachedRtt,omitempty"`
	// PTOAckDelay counts max_ack_delay in the probe timeout before the
	// handshake completes too, not only in 1-RTT as RFC 9002 does.
	PTOAckDelay bool `json:"ptoAckDelay,omitempty"`
	// Probe is what a handshake probe sends: ProbeFlight or
	// ProbeOnePacket. Empty: not measured (Safari).
	Probe string `json:"probe,omitempty"`
	// SkipPacketNumber skips one packet number before every probe, in the
	// handshake and 1-RTT, but not before a close.
	SkipPacketNumber bool `json:"skipPacketNumber,omitempty"`
	// Fresh and Resumed are when a handshake without and with a resumed
	// ticket gives up, and how it ends.
	Fresh   QUICGiveUp `json:"fresh"`
	Resumed QUICGiveUp `json:"resumed"`
	// AbandonClose is how the client ends an attempt dropped because TCP
	// won (HTTP3.Discovery.Fallback.AbandonOnTCP): CloseZeroRTT or empty.
	AbandonClose string `json:"abandonClose,omitempty"`
	// PathDegrading is when a live connection's path counts as dead and
	// what follows. Nil: never; the connection runs to its idle timeout.
	PathDegrading *QUICPathDegrading `json:"pathDegrading,omitempty"`
}

// Values of QUICLoss.Probe.
const (
	// ProbeFlight resends every first-flight Initial packet with the same
	// CRYPTO frames and new packet numbers (Firefox).
	ProbeFlight = "flight"
	// ProbeOnePacket sends one padded Initial carrying the first flight's
	// CRYPTO data packet by packet, cut afresh per Crypto.Split (Chrome).
	ProbeOnePacket = "one_packet"
)

// QUICGiveUp is when an unanswered handshake ends and what the client
// sends then.
type QUICGiveUp struct {
	// AfterMillis ends the attempt this long after it started if the
	// handshake is incomplete. Zero: it lasts until max_idle_timeout, or
	// is not measured.
	AfterMillis int `json:"afterMs,omitempty"`
	// Close is what the client sends at AfterMillis: CloseTransport,
	// CloseApplication, or empty for nothing (Firefox fresh).
	Close string `json:"close,omitempty"`
	// Reason is CloseTransport's reason phrase, "{elapsed_us}" replaced by
	// the microseconds since the attempt started.
	Reason string `json:"reason,omitempty"`
	// DatagramSize is the close datagram's padded size: inside the Initial
	// packet, or trailing zeros with CloseApplication.
	DatagramSize int `json:"datagramSize,omitempty"`
}

// Values of QUICGiveUp.Close and QUICLoss.AbandonClose.
const (
	// CloseTransport is CONNECTION_CLOSE 0x1c NO_ERROR with a reason in an
	// Initial packet, plus a coalesced 0-RTT copy if 0-RTT was sent.
	CloseTransport = "transport"
	// CloseApplication is an application close in an Initial packet, sent
	// as 0x1c APPLICATION_ERROR without reason (RFC 9000, 10.2.3), plus a
	// 0x1d close in 0-RTT if 0-RTT was sent.
	CloseApplication = "application"
	// CloseZeroRTT is a 0x1d H3_NO_ERROR close in its own 0-RTT packet if
	// 0-RTT was sent; nothing otherwise.
	CloseZeroRTT = "zero_rtt"
)

// QUICPathDegrading is a client's path-degrading rule. Exactly one of
// AfterPTOs and AfterMillis is set.
type QUICPathDegrading struct {
	// AfterPTOs: the path is degrading once the oldest unacknowledged
	// ack-eliciting packet is this many PTOs old, without back-off.
	AfterPTOs int `json:"afterPtos,omitempty"`
	// AfterMillis: the path is dead once nothing has arrived for this
	// long while a request waits.
	AfterMillis int `json:"afterMs,omitempty"`
	// Action is PathMigrate or PathClose.
	Action string `json:"action"`
	// CloseReason is PathClose's CONNECTION_CLOSE reason phrase.
	CloseReason string `json:"closeReason,omitempty"`
}

// Values of QUICPathDegrading.Action.
const (
	// PathMigrate moves to a new UDP socket and the server's next
	// connection ID: a padded PATH_CHALLENGE, RETIRE_CONNECTION_ID for the
	// old ID, then the unacknowledged data (Chrome).
	PathMigrate = "migrate"
	// PathClose sends CONNECTION_CLOSE (NO_ERROR, CloseReason) and moves
	// pending requests to a new connection (Fallback.Pending).
	PathClose = "close"
)

// QUICKeepAlive is the PING a client sends while a request waits for its
// response and nothing arrives: PeriodMillis after the moment From names,
// then every PeriodMillis. An idle connection sends none.
type QUICKeepAlive struct {
	// PeriodMillis is the PING period.
	PeriodMillis int `json:"periodMs"`
	// From is KeepAliveFromSent, KeepAliveFromIdle or
	// KeepAliveFromReceived.
	From string `json:"from"`
}

// Values of QUICKeepAlive.From.
const (
	// KeepAliveFromSent counts from the last ack-eliciting packet sent.
	KeepAliveFromSent = "sent"
	// KeepAliveFromIdle counts from the idle timer's last restart (RFC
	// 9000, section 10.1).
	KeepAliveFromIdle = "idle"
	// KeepAliveFromReceived counts from the last packet received.
	KeepAliveFromReceived = "received"
)

// QUICAck is how often a client acknowledges during a bulk receive. The
// ACK delay and ACK-only rules are QUIC's AckDelay and AckOnlyLimit.
type QUICAck struct {
	// Every acknowledges every Every-th ack-eliciting packet, or at
	// max_ack_delay.
	Every int `json:"every"`
	// WarmupPackets: until this many packets have arrived, acknowledge
	// every WarmupEvery-th instead.
	WarmupPackets int `json:"warmupPackets,omitempty"`
	WarmupEvery   int `json:"warmupEvery,omitempty"`
	// Batched waits until arrived packets are all read, so one ACK may
	// cover more than Every; otherwise exactly Every.
	Batched bool `json:"batched,omitempty"`
}

// QUICCredit is how a client returns flow-control credit. Its windows are
// its initial transport parameters (initial_max_stream_data_bidi_local,
// initial_max_data) and never grow: an update sets the limit to the bytes
// received plus the window.
type QUICCredit struct {
	// StreamDivisor sends MAX_STREAM_DATA once the bytes received since
	// the last update reach window / StreamDivisor.
	StreamDivisor int `json:"streamDivisor"`
	// ConnectionDivisor: MAX_DATA likewise for the connection. Zero with
	// ConnectionStreamWindow.
	ConnectionDivisor int `json:"connectionDivisor,omitempty"`
	// ConnectionStreamWindow sets the connection limit to bytes received
	// plus the stream window once that passes the initial limit, then
	// with every MAX_STREAM_DATA.
	ConnectionStreamWindow bool `json:"connectionStreamWindow,omitempty"`
}

// QUICKeyUpdate is how a client takes part in key updates.
type QUICKeyUpdate struct {
	// Initiate starts key updates of the client's own. No browser does;
	// each only follows the server's.
	Initiate bool `json:"initiate"`
}

// QUICVersionNegotiation is what a Version Negotiation packet makes a
// client do. Without Retry the attempt fails at once and no other version
// is tried.
type QUICVersionNegotiation struct {
	// Retry starts a new connection at once in a version the packet lists
	// from version_information's available ones.
	Retry bool `json:"retry"`
	// DowngradeError closes the retried connection with this error code
	// (0x1c) once the server's transport parameters lack
	// version_information (RFC 9368's downgrade check). Zero with Retry:
	// no check.
	DowngradeError QUICErrorCode `json:"downgradeError,omitempty"`
}

// QUICErrorCode is a QUIC transport error code. In JSON it is a hex
// string such as "0x53f8".
type QUICErrorCode uint64

// String returns the code in hex.
func (c QUICErrorCode) String() string {
	return "0x" + strconv.FormatUint(uint64(c), 16)
}

// MarshalText implements encoding.TextMarshaler.
func (c QUICErrorCode) MarshalText() ([]byte, error) {
	return []byte(c.String()), nil
}

// UnmarshalText accepts "0x" followed by hex digits.
func (c *QUICErrorCode) UnmarshalText(text []byte) error {
	s, ok := strings.CutPrefix(string(text), "0x")
	if !ok || s == "" {
		return fmt.Errorf("QUIC error code %q: want 0x and hex digits", text)
	}

	v, err := strconv.ParseUint(s, 16, 62)
	if err != nil {
		return fmt.Errorf("QUIC error code %q: %w", text, err)
	}

	*c = QUICErrorCode(v)

	return nil
}

// QUICCrypto is how the ClientHello is cut into CRYPTO frames across the
// client's Initial packets.
type QUICCrypto struct {
	// Split is CryptoSplitShuffle, CryptoSplitSNICut or CryptoSplitOrdered.
	Split string `json:"split"`
	// FirstPacket is how many ClientHello bytes the first Initial packet
	// carries with CryptoSplitOrdered.
	FirstPacket int `json:"firstPacket,omitempty"`
	// Head is the range of the length of the ClientHello's head that
	// stays in the first packet with CryptoSplitShuffle.
	Head *Range `json:"head,omitempty"`
	// AddedFrames is the range of how many times a packet's CRYPTO data is
	// split further with CryptoSplitShuffle, while padding lasts.
	AddedFrames *Range `json:"addedFrames,omitempty"`
	// Pings is the range of how many PING frames a packet gets with
	// CryptoSplitShuffle, while padding lasts.
	Pings *Range `json:"pings,omitempty"`
}

// Range is an inclusive range of integers.
type Range struct {
	Min int `json:"min"`
	Max int `json:"max"`
}

// Contains reports whether v is in r.
func (r Range) Contains(v int) bool {
	return v >= r.Min && v <= r.Max
}

// Values of QUIC.Padding.
const (
	// PaddingScattered spreads PADDING frames between the packet's other
	// frames (see CryptoSplitShuffle).
	PaddingScattered = "scattered"
	// PaddingTrailing pads the datagram with zero bytes after its last
	// packet; a datagram carrying a 1-RTT packet pads that packet instead.
	PaddingTrailing = "trailing"
	// PaddingEnd ends the packet with one run of PADDING frames.
	PaddingEnd = "end"
)

// Values of QUICCrypto.Split.
const (
	// CryptoSplitShuffle (Chrome, quiche's QuicChaosProtector): two
	// Initial packets; the first carries the hello's head [0, h), h in
	// Head, and its tail, so it holds floor((len-4)/2) bytes; the second
	// the middle. Each packet's CRYPTO data is split AddedFrames times,
	// gets Pings PINGs and scattered padding runs, and is shuffled; with
	// no padding left, nothing is added.
	CryptoSplitShuffle = "shuffle"
	// CryptoSplitSNICut (Firefox, neqo's SNI slicing): the hello is cut in
	// two mid server_name. With n = ceil(len/DatagramSize) and limit =
	// len/n, the longer piece is shortened so both fit limit; the first
	// packet carries the tail piece, then as much of the head piece as
	// fits, and the rest follows in order.
	CryptoSplitSNICut = "sni_cut"
	// CryptoSplitOrdered: one CRYPTO frame per packet, in order,
	// FirstPacket bytes in the first.
	CryptoSplitOrdered = "ordered"
)

// Values of QUIC.PacketNumbers.
const (
	// PacketNumbersShared numbers every packet from one counter from 1
	// across all spaces. The second Initial's number takes 2 bytes without
	// a token, else 1.
	PacketNumbersShared = "shared"
	// PacketNumbersRandomInitial numbers each space from 0, except Initial,
	// which starts at 1 + (a & 0x1f) + (max(b, 224) - 224) * 32 for random
	// bytes a and b (neqo). 1-RTT starts at 1 after 0-RTT, sharing its
	// space.
	PacketNumbersRandomInitial = "random_initial"
	// PacketNumbersPerSpace numbers each space from 0.
	PacketNumbersPerSpace = "per_space"
)

// DCIDLengthBiased picks max(8, 5 + (v & (v >> 4))) for a random byte v
// (neqo).
const DCIDLengthBiased = "biased"

// AckOnlyMaxData is a QUIC.AckOnlyFrame value: MAX_DATA with the
// connection's current limit.
const AckOnlyMaxData = "MAX_DATA"

// Values of QUIC.TransportParameterOrder.
const (
	// TransportParameterOrderFixed sends TransportParameters in order.
	TransportParameterOrderFixed = "fixed"
	// TransportParameterOrderShuffled sends them in a uniform random order
	// per connection.
	TransportParameterOrderShuffled = "shuffled"
	// TransportParameterOrderRotated sends a rotation starting at a random
	// one, those marked Last kept last in order.
	TransportParameterOrderRotated = "rotated"
)

// Values of QUIC.AckDelay.
const (
	// AckDelayActual reports the time since the largest acknowledged
	// packet arrived.
	AckDelayActual = "actual"
	// AckDelayConstant reports one value per connection, drawn from
	// QUIC.AckDelayConstant.
	AckDelayConstant = "constant"
)

// Values of QUIC.SpinBit.
const (
	// SpinBitZero always sends 0.
	SpinBitZero = "zero"
	// SpinBitRandom sends a random value per packet (RFC 9000, 17.4).
	SpinBitRandom = "random"
	// SpinBitSpin sends 0 until the handshake is confirmed, then the
	// inverse of the spin bit of the server's largest-numbered 1-RTT
	// packet since.
	SpinBitSpin = "spin"
)

// TransportParameter is one QUIC transport parameter. Its value is given
// in one of these ways, by ID:
//
//   - initial_source_connection_id: none; it is the client's Source
//     Connection ID (SCIDLength bytes).
//   - initial_rtt (0x3127): none; Resumed, and the RTT measured on the
//     connection whose ticket is resumed, in microseconds (Chrome).
//   - version_information (0x11): Versions.
//   - GREASE: MaxLength.
//   - Value for an integer parameter, Data for any other (absent: empty).
type TransportParameter struct {
	ID TransportParameterID `json:"id"`
	// Value is a parameter's value that is one variable-length integer.
	Value *uint64 `json:"value,omitempty"`
	// Data is the exact value of a parameter that is not an integer.
	Data Bytes `json:"data,omitempty"`
	// Versions of version_information (RFC 9368): the chosen version,
	// then the available ones. GREASEVersion stands for a reserved
	// version 0x?a?a?a?a, random per connection.
	Versions []QUICVersion `json:"versions,omitempty"`
	// ShuffleVersions sends the available versions in a random order per
	// connection (Chrome).
	ShuffleVersions bool `json:"shuffleVersions,omitempty"`
	// MaxLength is the longest random value of a GREASE parameter; its
	// length is uniform in [0, MaxLength].
	MaxLength int `json:"maxLength,omitempty"`
	// Resumed sends the parameter only on a resumed connection.
	Resumed bool `json:"resumed,omitempty"`
	// Last keeps the parameter last, in order, whatever
	// TransportParameterOrder permutes.
	Last bool `json:"last,omitempty"`
}

// Transport parameter IDs with special handling in profiles.
const (
	TPMaxIdleTimeout                TransportParameterID = 0x01
	TPMaxUDPPayloadSize             TransportParameterID = 0x03
	TPInitialMaxData                TransportParameterID = 0x04
	TPInitialMaxStreamDataBidiLocal TransportParameterID = 0x05
	TPInitialMaxStreamDataBidiRem   TransportParameterID = 0x06
	TPInitialMaxStreamDataUni       TransportParameterID = 0x07
	TPInitialMaxStreamsBidi         TransportParameterID = 0x08
	TPInitialMaxStreamsUni          TransportParameterID = 0x09
	TPAckDelayExponent              TransportParameterID = 0x0a
	TPMaxAckDelay                   TransportParameterID = 0x0b
	TPActiveConnectionIDLimit       TransportParameterID = 0x0e
	TPInitialSourceConnectionID     TransportParameterID = 0x0f
	TPVersionInformation            TransportParameterID = 0x11
	TPInitialRTT                    TransportParameterID = 0x3127
)

// TransportParameterID is a transport parameter's ID. In JSON it is a hex
// string such as "0x0f", or "GREASE" for a reserved ID (31 * N + 27, RFC
// 9000, section 18.1) picked at random per connection.
type TransportParameterID uint64

// GREASETransportParameter stands for any reserved transport parameter
// ID: the lowest, 27.
const GREASETransportParameter TransportParameterID = 27

// IsGREASETransportParameter reports a reserved transport parameter ID.
func IsGREASETransportParameter(id uint64) bool {
	return id >= 27 && (id-27)%31 == 0
}

// String returns "GREASE" or the ID in hex, at least two digits.
func (id TransportParameterID) String() string {
	if id == GREASETransportParameter {
		return "GREASE"
	}

	return fmt.Sprintf("0x%02x", uint64(id))
}

// MarshalText implements encoding.TextMarshaler.
func (id TransportParameterID) MarshalText() ([]byte, error) {
	return []byte(id.String()), nil
}

// UnmarshalText accepts "GREASE" or "0x" followed by hex digits. Unlike
// Code, a reserved ID in hex stays itself: browsers send real parameters
// in the reserved space (Firefox's min_ack_delay, 0xff02de1a).
func (id *TransportParameterID) UnmarshalText(text []byte) error {
	s := string(text)
	if s == "GREASE" {
		*id = GREASETransportParameter
		return nil
	}

	digits, ok := strings.CutPrefix(s, "0x")
	if !ok || digits == "" || len(digits) > 16 {
		return fmt.Errorf("invalid transport parameter %q: want \"GREASE\" or 0x followed by hex digits", s)
	}

	v, err := strconv.ParseUint(digits, 16, 62)
	if err != nil {
		return fmt.Errorf("invalid transport parameter %q: %w", s, err)
	}

	*id = TransportParameterID(v)

	return nil
}

// QUICVersion is a QUIC version. In JSON it is 8 hex digits with 0x, such
// as "0x00000001", or "GREASE" for a reserved version 0x?a?a?a?a (RFC
// 9000, section 15) picked at random per connection.
type QUICVersion uint32

// GREASEVersion stands for any reserved version: the lowest, 0x0a0a0a0a.
const GREASEVersion QUICVersion = 0x0a0a0a0a

// IsGREASEVersion reports a reserved QUIC version.
func IsGREASEVersion(v uint32) bool {
	return v&0x0f0f0f0f == 0x0a0a0a0a
}

// String returns "GREASE" or the version in hex.
func (v QUICVersion) String() string {
	if v == GREASEVersion {
		return "GREASE"
	}

	return fmt.Sprintf("0x%08x", uint32(v))
}

// MarshalText implements encoding.TextMarshaler.
func (v QUICVersion) MarshalText() ([]byte, error) {
	return []byte(v.String()), nil
}

// UnmarshalText accepts "GREASE" or "0x" followed by 1-8 hex digits. Any
// reserved version is stored as GREASEVersion.
func (v *QUICVersion) UnmarshalText(text []byte) error {
	s := string(text)
	if s == "GREASE" {
		*v = GREASEVersion
		return nil
	}

	digits, ok := strings.CutPrefix(s, "0x")
	if !ok || digits == "" || len(digits) > 8 {
		return fmt.Errorf("invalid QUIC version %q: want \"GREASE\" or 0x followed by 1-8 hex digits", s)
	}

	n, err := strconv.ParseUint(digits, 16, 32)
	if err != nil {
		return fmt.Errorf("invalid QUIC version %q: %w", s, err)
	}

	if IsGREASEVersion(uint32(n)) {
		*v = GREASEVersion
		return nil
	}

	*v = QUICVersion(n)

	return nil
}

// QUICHello is how a browser's QUIC ClientHello differs from its TLS one
// (Profile.TLS): TLS's extensions without Drop, Replace applied, plus
// quic_transport_parameters, ordered per ExtensionOrder. A resumed hello
// (QUIC.ZeroRTT) also applies TLS.Resumption.Drop where TLS resumes,
// adds early_data, and ends with pre_shared_key. Required with
// Profile.QUIC; derived by internal/harness/cmd/hellogen.
type QUICHello struct {
	// CipherSuites replaces TLS.CipherSuites. Required.
	CipherSuites []Code `json:"cipherSuites"`
	// SessionIDLength is legacy_session_id's length (RFC 9001, section
	// 8.4).
	SessionIDLength uint8 `json:"sessionIdLength"`
	// ExtensionOrder is ExtensionOrderFixed or ExtensionOrderShuffled,
	// independent of TLS's.
	ExtensionOrder string `json:"extensionOrder"`
	// Last are extensions a shuffled hello keeps last, in this order,
	// before pre_shared_key.
	Last []Code `json:"last,omitempty"`
	// Drop are TLS's extensions the hello leaves out; GREASE drops both
	// GREASE extensions.
	Drop []Code `json:"drop,omitempty"`
	// Replace are extensions whose bodies differ from TLS's, each
	// replacing the one of its type in place.
	Replace []Extension `json:"replace,omitempty"`
	// TransportParametersBefore is the extension quic_transport_parameters
	// precedes in a fixed order. Required with ExtensionOrderFixed.
	TransportParametersBefore *Code `json:"transportParametersBefore,omitempty"`
	// EarlyDataBefore is the extension early_data precedes in a resumed
	// hello of a fixed order (Safari: supported_versions); nil puts it
	// after the others, before Last.
	EarlyDataBefore *Code `json:"earlyDataBefore,omitempty"`
	// ResumedECHPayloadLengths are GREASE ECH's payload lengths in a
	// resumed hello. Required with QUIC.ZeroRTT and
	// encrypted_client_hello.
	ResumedECHPayloadLengths []uint16 `json:"resumedEchPayloadLengths,omitempty"`
	// VersionNegotiation is how the hello of a connection retried after
	// Version Negotiation differs from a full one. Nil: the profile does
	// not retry.
	VersionNegotiation *QUICHelloRetry `json:"versionNegotiation,omitempty"`
}

// QUICHelloRetry is how a retried QUIC hello differs from a full one.
type QUICHelloRetry struct {
	// Drop are the full hello's extensions it leaves out.
	Drop []Code `json:"drop,omitempty"`
	// Replace are extensions whose bodies differ, each replacing the one
	// of its type in place.
	Replace []Extension `json:"replace,omitempty"`
	// Padding adds padding (0x0015) last, sized as NSS and BoringSSL
	// size it: a hello of 256 to 511 bytes is padded to 512.
	Padding bool `json:"padding,omitempty"`
}

// Extension types QUIC hellos add.
const (
	ExtEarlyData               Code = 0x002a
	ExtQUICTransportParameters Code = 0x0039
)
